# boxctl: timeout=120
W=~/work/sidnet; tail -6 $W/logs/timeline.log | cut -c1-260; for f in labelB build buildB; do [ -f $W/logs/$f.log ] && echo "$f: $(tail -1 $W/logs/$f.log | cut -c1-200)"; done; [ -f $W/logs/s0.err ] && echo "s0.err: $(tail -1 $W/logs/s0.err | cut -c1-200)"; [ -f $W/labelsB/errors.jsonl ] && echo "labelsB errors: $(wc -l < $W/labelsB/errors.jsonl); sidecars $(ls $W/labelsB | grep -c npz$)"; ls $W/shards 2>/dev/null | grep -c npz$ | sed "s/^/shard files built: /"; echo "units: $(systemctl is-active sidnet-run sidnet-run2 | tr "\n" " ")"; uptime | sed "s/.*load/load/"; free -g | sed -n 2p | cut -c1-70; df -h $HOME | tail -1
